for cle, val in {"NUIT2": NUIT2, "NUIT": NUIT, "ROYAL": ROYAL, "CIEL": CIEL, "CLAIR": CLAIR, "PALE": PALE}.items():
    CSS = CSS.replace(f"@{cle}@", val)
