# =========================================================
# 3. OUTILS D'AFFICHAGE (compatibles anciennes et nouvelles versions de Streamlit)
# =========================================================
def etendre(fonction, *args, **kwargs):
    try:
        return fonction(*args, width="stretch", **kwargs)
    except Exception:
        return fonction(*args, use_container_width=True, **kwargs)


def boite(texte, titre=""):
    t = f'<b class="t">{titre}</b>' if titre else ""
    st.markdown(f'<div class="callout">{t}{texte}</div>', unsafe_allow_html=True)


def espace(v):
    return f"{int(v):,}".replace(",", " ")


def court(texte, largeur=24):
    return "<br>".join(textwrap.wrap(texte, largeur))


def rgba(hexa, alpha):
    h = hexa.lstrip("#")
    return f"rgba({int(h[0:2], 16)},{int(h[2:4], 16)},{int(h[4:6], 16)},{alpha})"


def habiller(fig, hauteur=440, **extra):
    mise = dict(
        height=hauteur, paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Segoe UI, Inter, Arial, sans-serif", size=13, color="#CFE6FF"),
        margin=dict(l=20, r=20, t=25, b=25),
        hoverlabel=dict(bgcolor=NUIT, bordercolor=CLAIR, font=dict(color="#FFFFFF", size=13)),
        legend=dict(orientation="h", yanchor="top", y=-0.12, xanchor="center", x=0.5, font=dict(size=11, color="#CFE6FF")),
    )
    mise.update(extra)
    fig.update_layout(**mise)
    fig.update_xaxes(gridcolor="rgba(127,211,255,.12)", zeroline=False, linecolor="rgba(127,211,255,.25)", tickfont=dict(color="#CFE6FF"))
    fig.update_yaxes(gridcolor="rgba(127,211,255,.12)", zeroline=False, linecolor="rgba(127,211,255,.25)", tickfont=dict(color="#CFE6FF"))
    return fig


