# 4. DONNÉES
# =========================================================
def creer_donnees_demo(n=300):
    rng = np.random.default_rng(42)
    return pd.DataFrame({
        "Patient_ID": [f"P-{i:05d}" for i in range(1, n + 1)],
        "Age": rng.integers(18, 90, n),
        "Sexe": rng.choice(["Femme", "Homme"], n),
        "IMC": np.clip(rng.normal(27, 5.5, n), 15, 48).round(1),
        "Fumeur": rng.choice(["Oui", "Non"], n, p=[0.32, 0.68]),
        "Hospitalisations": np.clip(rng.poisson(1.2, n), 0, 10),
        "Region": rng.choice(["Thiès", "Dakar", "Diourbel", "Louga", "Saint-Louis"], n),
    })


def lire_fichier_csv(fichier):
    """Lit tout le CSV (sans limite de lignes) avec les encodages et séparateurs courants."""
    if hasattr(fichier, "getvalue"):
        contenu = fichier.getvalue()
    elif hasattr(fichier, "read_bytes"):
        contenu = fichier.read_bytes()
    elif hasattr(fichier, "read"):
        contenu = fichier.read()
    else:
        contenu = Path(fichier).read_bytes()
    if not contenu:
        raise ValueError("Le fichier CSV est vide ou illisible.")
    derniere = None
    for enc in ("utf-8-sig", "utf-8", "cp1252", "latin1"):
        for sep in (None, ";", ",", "\t", "|"):
            try:
                if sep is None:
                    df = pd.read_csv(BytesIO(contenu), sep=None, engine="python", encoding=enc)
                else:
                    df = pd.read_csv(BytesIO(contenu), sep=sep, encoding=enc, low_memory=False)
                df.columns = [str(c).strip().replace("\ufeff", "") for c in df.columns]
                if len(df.columns) == 1 and any(s in contenu[:4096].decode(enc, errors="ignore") for s in (";", ",", "\t", "|")):
                    derniere = ValueError("Séparateur non détecté.")
                    continue
                if len(df) == 0:
                    raise ValueError("Le CSV ne contient aucune ligne de données.")
                return df
            except Exception as exc:
                derniere = exc
    raise ValueError(f"Impossible de lire le CSV. Détail : {derniere}")


def charger_donnees():
    chemin = Path("patients.csv")
    if chemin.exists():
        try:
            return lire_fichier_csv(chemin), "Fichier patients.csv"
        except Exception:
            pass
    return creer_donnees_demo(), "Données fictives de démonstration"


def preparer_donnees(df):
    df = df.copy()
    colonnes = ["Patient_ID", "Age", "Sexe", "IMC", "Fumeur", "Hospitalisations", "Region"]
    defaut = {"Age": 40, "Sexe": "Inconnu", "IMC": 25, "Fumeur": "Non", "Hospitalisations": 0, "Region": "Non renseignée"}
    for col in colonnes:
        if col not in df.columns:
            df[col] = [f"P-{i:05d}" for i in range(1, len(df) + 1)] if col == "Patient_ID" else defaut[col]
    for col in ["Age", "IMC", "Hospitalisations"]:
        df[col] = pd.to_numeric(df[col], errors="coerce")
        med = df[col].median()
        df[col] = df[col].fillna(med if pd.notna(med) else defaut[col])
    for col in ["Sexe", "Fumeur", "Region", "Patient_ID"]:
        df[col] = df[col].fillna("Inconnu").astype(str).str.strip()
    df["Age"] = df["Age"].clip(0, 120)
    df["IMC"] = df["IMC"].clip(0, 100)
    df["Hospitalisations"] = df["Hospitalisations"].clip(lower=0).round().astype(int)
    df["Fumeur_binaire"] = df["Fumeur"].str.lower().map(
        {"oui": 1, "yes": 1, "1": 1, "true": 1, "non": 0, "no": 0, "0": 0, "false": 0}).fillna(0).astype(int)
    df["Fumeur"] = np.where(df["Fumeur_binaire"] == 1, "Oui", "Non")
    return df


FEATURES = ["Age", "IMC", "Fumeur_binaire", "Hospitalisations"]


def calculer_segmentation(df):
    df = df.copy()
    if len(df) == 0:
        return df
    if len(df) < 3:
        df["Cluster"] = 0
        df["Profil"] = PROFILS[0]
        return df
    X_scaled = StandardScaler().fit_transform(df[FEATURES].astype(float))
    df["Cluster"] = AgglomerativeClustering(n_clusters=3, linkage="ward").fit_predict(X_scaled)
    st_ = df.groupby("Cluster").agg(age=("Age", "mean"), imc=("IMC", "mean"), fum=("Fumeur_binaire", "mean"), hosp=("Hospitalisations", "mean"))
    senior = int((st_["age"].rank(pct=True) + st_["hosp"].rank(pct=True)).idxmax())
    autres = [c for c in st_.index if c != senior]
    if len(autres) >= 2:
        fumeur = int((st_.loc[autres, "imc"].rank(pct=True) + st_.loc[autres, "fum"].rank(pct=True)).idxmax())
        routine = next(c for c in autres if c != fumeur)
    else:
        fumeur = routine = autres[0] if autres else senior
    df["Profil"] = df["Cluster"].map({routine: PROFILS[0], senior: PROFILS[1], fumeur: PROFILS[2]}).fillna(PROFILS[0])
    return df


def generer_alertes(df):
    df = df.copy()
    if df.empty:
        for c in ("Nombre_facteurs_alerte", "Niveau_alerte", "Recommandation"):
            df[c] = []
        return df
    conds = [df["Age"] >= 65, df["IMC"] >= 30, df["Hospitalisations"] >= 3, df["Fumeur_binaire"] == 1]
    df["Nombre_facteurs_alerte"] = sum(c.astype(int) for c in conds)
    df["Niveau_alerte"] = df["Nombre_facteurs_alerte"].apply(lambda n: "Critique" if n >= 3 else "Élevé" if n == 2 else "Modéré" if n == 1 else "Faible")

    def reco(r):
        p = []
        if r["Age"] >= 65: p.append("Examiner les besoins de suivi liés à l'âge")
        if r["IMC"] >= 30: p.append("Évaluer les facteurs associés à l'IMC")
        if r["Hospitalisations"] >= 3: p.append("Revoir l'historique des hospitalisations")
        if r["Fumeur_binaire"] == 1: p.append("Évaluer les besoins d'accompagnement au sevrage")
        return " ; ".join(p) + "." if p else "Poursuivre le suivi selon le dossier clinique."
    df["Recommandation"] = df.apply(reco, axis=1)
    return df


if "patients_base" not in st.session_state:
    d, s = charger_donnees()
    st.session_state["patients_base"] = preparer_donnees(d)
    st.session_state["source_donnees"] = s

df_base = st.session_state["patients_base"].copy()
df_alertes = generer_alertes(calculer_segmentation(df_base))

# ---------- Préparation du modèle KNN ----------
COLONNES_TECHNIQUES = {"Fumeur_binaire", "Cluster", "Profil", "Nombre_facteurs_alerte", "Niveau_alerte", "Recommandation"}


def est_identifiant(nom):
    n = "".join(ch.lower() for ch in str(nom) if ch.isalnum())
    termes = ("patientid", "idpatient", "identifiant", "numerodossier", "telephone", "email", "adresse", "nompatient", "prenompatient")
    return n in {"id", "uuid", "email", "telephone", "phone"} or any(t in n for t in termes)


colonnes_knn = [c for c in df_base.columns
                if c not in COLONNES_TECHNIQUES and not est_identifiant(c)
                and df_base[c].notna().sum() > 0 and df_base[c].nunique(dropna=True) > 1]

knn = label_encoder = scaler_knn = None
colonnes_encodees = []
if len(df_alertes) >= 3 and colonnes_knn:
    dk = df_base[colonnes_knn].copy()
    for c in colonnes_knn:
        if pd.api.types.is_numeric_dtype(dk[c]):
            dk[c] = pd.to_numeric(dk[c], errors="coerce")
            m = dk[c].median()
            dk[c] = dk[c].fillna(0 if pd.isna(m) else m)
        else:
            dk[c] = dk[c].fillna("Non renseigné").astype(str).str.strip()
    Xk = pd.get_dummies(dk, dummy_na=False, dtype=float)
    Xk = Xk.loc[:, Xk.nunique(dropna=False) > 1]
    colonnes_encodees = list(Xk.columns)
    if Xk.shape[1] > 0:
        scaler_knn = StandardScaler()
        Xs = scaler_knn.fit_transform(Xk.astype(float))
        label_encoder = LabelEncoder()
        y = label_encoder.fit_transform(df_alertes["Profil"].astype(str))
        knn = KNeighborsClassifier(n_neighbors=min(5, len(df_alertes))).fit(Xs, y)

